#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

#define SIZE (64UL << 20)

static void run(const char *tag, int advice) {
    void *p;
    posix_memalign(&p, 2UL << 20, SIZE);          /* aligned to the 2 MB huge page size */
    madvise(p, SIZE, advice);
    memset(p, 1, SIZE);                            /* touch everything */
    char cmd[160];
    snprintf(cmd, sizeof cmd, "printf '%%-22s' '%s'; grep AnonHugePages /proc/%d/smaps_rollup | awk '{print $2, $3}'", tag, getpid());
    system(cmd);
    free(p);
}

int main(void) {
    run("MADV_NOHUGEPAGE:", MADV_NOHUGEPAGE);
    run("MADV_HUGEPAGE:", MADV_HUGEPAGE);
    return 0;
}

